import { createContext, useContext, useState } from "react";

// Tạo context giỏ hàng
const CartContext = createContext();

export const CartProvider = ({ children }) => {
    // State cho giỏ hàng và danh sách đơn hàng
    const [cart, setCart] = useState([]);
    const [orders, setOrders] = useState([]); // ✅ Thêm state orders

    // Thêm sản phẩm vào giỏ hàng
    const addToCart = (product) => {
        setCart((prevCart) => {
            // Kiểm tra nếu sản phẩm đã có trong giỏ hàng
            const existingProduct = prevCart.find((item) => item.id === product.id);
            if (existingProduct) {
                // Nếu sản phẩm đã có, chỉ cập nhật số lượng
                return prevCart.map((item) =>
                    item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
                );
            }
            // Nếu sản phẩm chưa có, thêm mới vào giỏ hàng với số lượng là 1
            return [...prevCart, { ...product, quantity: 1 }];
        });
    };

    // Xóa sản phẩm khỏi giỏ hàng
    const removeFromCart = (id) => {
        setCart((prevCart) => prevCart.filter((item) => item.id !== id));
    };

    // Cập nhật số lượng sản phẩm
    // Cập nhật số lượng sản phẩm
    const updateQuantity = (productId, action) => {
        setCart((prevCart) => {
            return prevCart.map((product) => {
                if (product.id === productId) {
                    if (action === "increase") {
                        return { ...product, quantity: product.quantity + 1 };
                    } else if (action === "decrease" && product.quantity > 1) {
                        return { ...product, quantity: product.quantity - 1 };
                    }
                }
                return product;
            });
        });
    };

    // Tính tổng số lượng sản phẩm
    const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

    // Tính tổng giá trị đơn hàng (cần nhân với số lượng của mỗi sản phẩm)
    const totalPrice = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

    // Xử lý thanh toán và tạo đơn hàng mới
    const checkout = () => {
        if (cart.length === 0) {
            alert("Giỏ hàng trống!");
            return;
        }

        // Tạo đơn hàng mới
        const newOrder = {
            id: orders.length + 1,
            items: [...cart],
            total: totalPrice,
            date: new Date().toLocaleString(),
        };

        // Lưu đơn hàng vào danh sách
        setOrders((prevOrders) => [...prevOrders, newOrder]); // ✅ Cập nhật orders

        // Xóa giỏ hàng sau khi thanh toán
        setCart([]);

        alert("Đơn hàng của bạn đã được đặt thành công!");
    };

    return (
        <CartContext.Provider
            value={{
                cart,
                addToCart,
                removeFromCart,
                totalItems,
                totalPrice,
                checkout,
                orders,
                setOrders, // ✅ Truyền setOrders vào context
                updateQuantity, // Truyền updateQuantity vào context
            }}
        >
            {children}
        </CartContext.Provider>
    );
};

// Hook để sử dụng giỏ hàng trong các component
export const useCart = () => useContext(CartContext);
